package main

import (
	"encoding/hex"
	"fmt"

	"github.com/brian-nunez/computer-craft/external/internal/protocol"
)

// Fixed development inputs. These are fixture material, never a credential:
// a real World Key is generated by the External Application with crypto/rand.
const (
	fixtureRootSecretHex = "0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0"
	fixtureClientNonce   = "11111111111111111111111111111111111111111111111111111111aaaaaaaa"
	fixtureParentNonce   = "22222222222222222222222222222222222222222222222222222222bbbbbbbb"
	fixtureSessionNonce  = "33333333333333333333333333333333333333333333333333333333cccccccc"
	fixtureParentSession = "44444444444444444444444444444444444444444444444444444444dddddddd"
)

func mustHex(text string) []byte {
	raw, err := hex.DecodeString(text)
	if err != nil {
		fail(err)
	}
	return raw
}

// writeDerivation records the purpose-separated derivation chain: an enrollment
// secret from a root secret, a relationship credential from the enrollment
// transcript, a session key from the session transcript, and a derived nonce.
// Both languages must reproduce every step exactly.
func writeDerivation() {
	rootSecret := mustHex(fixtureRootSecretHex)

	enrollmentSecret, err := protocol.EnrollmentSecret(rootSecret, "isp", 7)
	if err != nil {
		fail(err)
	}

	enrollment := protocol.EnrollmentTranscript{
		RequestedName:  "acme",
		Role:           "isp",
		ParentID:       "central-overworld",
		RelationshipID: "rel-acme-0001",
		ClientNonce:    fixtureClientNonce,
		ParentNonce:    fixtureParentNonce,
		ParentRevision: 12,
	}
	credential, err := protocol.RelationshipCredential(enrollmentSecret, enrollment.Object())
	if err != nil {
		fail(err)
	}

	// A re-enrolling child carries its existing identity into the transcript, so
	// the same secret and nonces must still derive a different credential.
	reEnrollment := enrollment
	reEnrollment.ChildID = "isp-acme"
	reCredential, err := protocol.RelationshipCredential(enrollmentSecret, reEnrollment.Object())
	if err != nil {
		fail(err)
	}
	if hex.EncodeToString(credential) == hex.EncodeToString(reCredential) {
		fail(fmt.Errorf("re-enrollment must not derive the first enrollment credential"))
	}

	session := protocol.SessionTranscript{
		RelationshipID: "rel-acme-0001",
		SessionID:      "ses-000042",
		ClientNonce:    fixtureSessionNonce,
		ParentNonce:    fixtureParentSession,
		ChildRevision:  3,
		ParentRevision: 12,
	}
	sessionKey, err := protocol.SessionKey(credential, session.Object())
	if err != nil {
		fail(err)
	}

	childNonce, err := protocol.Nonce(credential, "isp", 1)
	if err != nil {
		fail(err)
	}
	parentNonce, err := protocol.Nonce(credential, "central", 1)
	if err != nil {
		fail(err)
	}

	record("derivation/keys.json", "key_derivation", "valid", both(), protocol.Object{
		"schema": int64(1),
		"note": "Every value is derived, not stored. Labels are purpose separated so that " +
			"one credential can never stand in for another.",
		"labels": protocol.Object{
			"enrollment":   protocol.LabelEnrollment,
			"relationship": protocol.LabelRelationship,
			"session":      protocol.LabelSession,
			"nonce":        protocol.LabelNonce,
		},
		"root_secret_hex": fixtureRootSecretHex,
		"enrollment_secret": protocol.Object{
			"child_role":        "isp",
			"token_use_counter": int64(7),
			"value":             hex.EncodeToString(enrollmentSecret),
		},
		"relationship_credential": protocol.Object{
			"transcript": enrollment.Object(),
			"value":      hex.EncodeToString(credential),
		},
		"re_enrollment_credential": protocol.Object{
			"transcript": reEnrollment.Object(),
			"value":      hex.EncodeToString(reCredential),
		},
		"session_key": protocol.Object{
			"transcript": session.Object(),
			"value":      hex.EncodeToString(sessionKey),
		},
		"nonces": protocol.Array{
			protocol.Object{"role": "isp", "generation": int64(1), "value": childNonce},
			protocol.Object{"role": "central", "generation": int64(1), "value": parentNonce},
		},
	})
}
